-- GARDA INFLASI - Data Eksekusi Ingestion & Data Mentah Bronze Demo

-- =====================================================================
-- Pembaruan Status Demo Sumber Data
-- =====================================================================
UPDATE sumber_data SET
  status = v.status::status_sumber,
  terakhir_jalan = CURRENT_TIMESTAMP - (v.menit_lalu || ' minutes')::interval,
  keberhasilan_7h = v.keberhasilan_7h,
  latensi_ms = v.latensi_ms
FROM (VALUES
  ('SRC-BPS', 'SEHAT', 142, 100.0, 640),
  ('SRC-BI', 'SEHAT', 38, 98.6, 910),
  ('SRC-DJPB', 'SEHAT', 2880, 100.0, 1220),
  ('SRC-BMKG', 'SEHAT', 51, 99.1, 480),
  ('SRC-OWM', 'SEHAT', 12, 99.8, 210),
  ('SRC-BAPANAS', 'TERTUNDA', 325, 86.4, 3400),
  ('SRC-PORTAL', 'GAGAL', 1460, 57.1, 0),
  ('SRC-CS', 'SEHAT', 3, 99.97, 95)
) AS v(kode, status, menit_lalu, keberhasilan_7h, latensi_ms)
WHERE sumber_data.kode = v.kode;

-- =====================================================================
-- Tabel: eksekusi_sumber (32 baris)
-- =====================================================================
ON CONFLICT (id) DO NOTHING;

-- =====================================================================
-- Tabel: data_mentah (22 baris)
-- =====================================================================
ON CONFLICT (id) DO NOTHING;

-- =====================================================================
-- Tabel: harga_eksternal (340 baris)
-- =====================================================================
ON CONFLICT (sumber_id, komoditas_kode, kabupaten_kode, tanggal, tipe) DO NOTHING;

-- Sinkronisasi sequence identity / serial
SELECT setval(pg_get_serial_sequence('eksekusi_sumber', 'id'), COALESCE((SELECT max(id) FROM eksekusi_sumber), 1));
SELECT setval(pg_get_serial_sequence('data_mentah', 'id'), COALESCE((SELECT max(id) FROM data_mentah), 1));

